function mergePointValue(headA: ListNode | null, headB: ListNode | null): number {
  // equal values stand in for "same node" in this version
  const same = (x: ListNode | null, y: ListNode | null) => x === y || (!!x && !!y && x.val === y.val);
  let p = headA, q = headB;
  while (!same(p, q)) {
    p = p ? p.next : headB;
    q = q ? q.next : headA;
  }
  return p ? p.val : -1;
}

